/**
 * The seven k-means datasets, read from the JSON both languages share.
 *
 * `datasets.json` is generated by `py/datasets.py` (`mise run sync kmeans`) — the points are
 * not regenerated here, which is why this port no longer carries a copy of CPython's Mersenne
 * Twister just to agree with Python about `gauss()`.
 */

import { readFileSync } from "node:fs";

import type { Point } from "../../../ts/src/dataviz.ts";

// Read, not imported: a JSON import needs an attribute node insists on and ts-node rejects.
const datasets = JSON.parse(readFileSync(new URL("../datasets.json", import.meta.url), "utf8")) as Record<string, number[][]>;

export const DATASETS: Record<string, Point[]> = Object.fromEntries(
  Object.entries(datasets).map(([name, points]) => [name, points.map(([x, y]) => [x!, y!] as Point)]),
);

export const { TWENTY, BLOBS, TIGHT, LOPSIDED, ELONGATED, UNSCALED, UNIFORM } = DATASETS as Record<string, Point[]> & {
  TWENTY: Point[];
  BLOBS: Point[];
  TIGHT: Point[];
  LOPSIDED: Point[];
  ELONGATED: Point[];
  UNSCALED: Point[];
  UNIFORM: Point[];
};
